  "anomalies": [
    {
      "category": "short_to_supply",
      "components": ["U4"],
      "pins": ["U4.8"],
      "nets": ["+5V", "NET0011"],
      "observed": "The ATtiny45 THT footprint U4 is shown with pin 8 connected to NET0011, the potentiometer wiper net, while the U4 VCC pin is tied to +5V. Pin 2 (PB3/XTAL1 on an ATtiny45) is not shown connected to NET0011.",
      "expected": "For an ATtiny45-20P, pin 8 is VCC and pin 2 is PB3/XTAL1. The pot wiper net NET0011 should connect to U4 pin 2, and U4 pin 8 should connect only to the +5V supply.",
      "evidence": [
        {"source": "schematic", "quote": "U4 ATtiny45-20P ... VCC +5V ... 8 NET0011"},
        {"source": "schematic", "quote": "J6 POT ... 2 NET0011"},
        {"source": "spec", "quote": "an ATtiny-driven fan controller"}
      ],
      "impact": "If U4 is populated, +5V is shorted to the potentiometer/ADC input net, forcing a constant high on the pot wiper, loading the potentiometer, preventing manual speed control, and potentially damaging the MCU or potentiometer.",
      "confidence": 0.85
    }
  ],
  "summary": "An anomaly is detected: the ATtiny45 footprint appears wired using the ATtiny13 pin mapping, putting the pot wiper net on U4 pin 8 (VCC) instead of pin 2 and thereby shorting +5V to NET0011."
}

